// Shared UI component entry. Start with the global shell and top filters.
const SHELL_THEME={
  brandName:'网球兄弟',
  brandSubline:'TENNISFLOW',
  brandColor:'#FBF7F4',
  brandSublineColor:'#CAB6A8',
  sidebarBg:'#805435',
  sidebarDivider:'#875C3C',
  appShellBg:'#875C3C',
  topbarDivider:'#805435',
  pageTitleColor:'#FBF7F4',
  liveClockColor:'#E0D3C9',
  liveDotColor:'#78DB89',
  sidebarIconColor:'#C5B0A2',
  sidebarActiveIconColor:'#EFE7E2'
};
function applyShellThemeVars(){
  const root=document.documentElement;
  root.style.setProperty('--shell-brand-color',SHELL_THEME.brandColor);
  root.style.setProperty('--shell-brand-subline-color',SHELL_THEME.brandSublineColor);
  root.style.setProperty('--shell-sidebar-bg',SHELL_THEME.sidebarBg);
  root.style.setProperty('--shell-sidebar-divider',SHELL_THEME.sidebarDivider);
  root.style.setProperty('--shell-app-bg',SHELL_THEME.appShellBg);
  root.style.setProperty('--shell-topbar-divider',SHELL_THEME.topbarDivider);
  root.style.setProperty('--shell-page-title-color',SHELL_THEME.pageTitleColor);
  root.style.setProperty('--shell-live-clock-color',SHELL_THEME.liveClockColor);
  root.style.setProperty('--shell-live-dot-color',SHELL_THEME.liveDotColor);
  root.style.setProperty('--shell-sidebar-icon-color',SHELL_THEME.sidebarIconColor);
  root.style.setProperty('--shell-sidebar-active-icon-color',SHELL_THEME.sidebarActiveIconColor);
}
